  test('adjustment formulas match the reference values through the UI', async () => {
    const expected = await (await fetch(FIXTURE_BASE + 'color_fixture.expected.json')).json();
    await h.open(expected.image);
    const { width, height } = h.editor.doc;
    if (width !== expected.width || height !== expected.height) throw new Error('fixture size mismatch');

    // The decoded fixture must equal the reference input, then every case must
    // reproduce the numpy result after Apply.
    // A fully transparent pixel has no colour after premultiplication, so only
    // alpha is comparable there.
    for (let i = 0; i < width * height; i++) {
      const px = h.sample(i % width, Math.floor(i / width));
      const [r, g, b] = [expected.input[i * 3], expected.input[i * 3 + 1], expected.input[i * 3 + 2]];
      if (px.a !== expected.alpha[i]) {
        throw new Error(`fixture pixel ${i} has alpha ${px.a}, expected ${expected.alpha[i]}`);
      }
      if (px.a === 0) continue;
      const tolerance = h.alphaTolerance(px.a);
      if (Math.abs(px.r - r) > tolerance || Math.abs(px.g - g) > tolerance || Math.abs(px.b - b) > tolerance) {
        throw new Error(`fixture pixel ${i} decoded as ${JSON.stringify(px)}, expected rgba(${r},${g},${b},${expected.alpha[i]})`);
      }
    }

    for (const testCase of expected.cases) {
      h.setValue('brightness', testCase.opts.brightness);
      h.setValue('contrast', testCase.opts.contrast);
      h.setValue('grayscaleToggle', testCase.opts.grayscale);
      h.setValue('invertToggle', testCase.opts.invert);
      h.editor.scheduleAdjustPreview(0);
      await h.waitFor(() => !h.editor.busy.busy && (h.editor.adjustments.active === !(testCase.name === 'identity')));
      await h.settle();
      h.click('adjustApply');
      await h.settle();

      for (let i = 0; i < width * height; i++) {
        const px = h.sample(i % width, Math.floor(i / width));
        if (px.a !== expected.alpha[i]) throw new Error(`${testCase.name}: alpha changed to ${px.a}`);
        // Translucent pixels are excluded from the colour comparison: their stored
        // input already differs from the reference by the premultiplication step
        // above, so an exact comparison would test the canvas backend, not the
        // formula. Alpha preservation is asserted for every pixel, and the Node
        // unit test checks the formulas exhaustively against numpy.
        if (px.a !== 255) continue;
        const expectedRgb = [testCase.expected[i * 3], testCase.expected[i * 3 + 1], testCase.expected[i * 3 + 2]];
        if (px.r !== expectedRgb[0] || px.g !== expectedRgb[1] || px.b !== expectedRgb[2]) {
          throw new Error(`${testCase.name}: pixel ${i} is rgb(${px.r},${px.g},${px.b}), reference says rgb(${expectedRgb.join(',')})`);
        }
      }
      h.key('z', { ctrlKey: true });
      await h.settle();
      h.editor.resetAdjustmentControls();
      await h.settle();
    }
  });

